// Botomatik Pattern: Find repeat customers with last order
// Reference: docs/core/verified-research-findings.md - Botomatik 15% conversion uplift

const orders = $input.item.json || [];
const tenantId = $('Split Tenants').first().json.id;

// Group by customer phone, get most recent order
const customerOrders = {};
orders.forEach(order => {
  const phone = order.customer_phone;
  if (!customerOrders[phone] || new Date(order.created_at) > new Date(customerOrders[phone].created_at)) {
    customerOrders[phone] = order;
  }
});

// Filter: Only customers with orders in last 14 days (recent enough to reorder)
const now = new Date();
const twoWeeksAgo = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000);

const eligibleCustomers = Object.values(customerOrders).filter(order => {
  const orderDate = new Date(order.created_at);
  return orderDate >= twoWeeksAgo;
});

return eligibleCustomers.map(order => ({
  tenant_id: tenantId,
  customer_phone: order.customer_phone,
  last_order_items: order.items,
  last_order_amount: order.total_amount,
  last_order_date: order.created_at
}));

// Format reorder message (Botomatik pattern)
// Reference: docs/core/verified-research-findings.md - 60% abandoned cart recovery

const customer = $input.item.json;
const items = customer.last_order_items || [];

// Format items list
let itemsText = '';
items.forEach((item, index) => {
  const name = item.name || item.product || 'Item';
  const qty = item.qty || 1;
  const price = item.price || 0;
  itemsText += `${index + 1}. ${name} - ${qty} × KSh ${price}\n`;
});

const message = `🛒 Quick reorder? Same as last time:

${itemsText}
💰 Total: KSh ${customer.last_order_amount}

Reply YES to order now.`;

return {
  tenant_id: customer.tenant_id,
  customer_phone: customer.customer_phone,
  message: message,
  last_order_amount: customer.last_order_amount,
  last_order_items: customer.last_order_items
};
